    "targetSounds": [
      "Mastery of weak forms and reductions: 'could you' /ˈkʊdʒuː/, 'would you' /ˈwʊdʒuː/, 'congratulations on' /kənˌɡrætʃ.əˈleɪ.ʃənz ɒn/",
      "Rhythmic sentence stress across multi-clause complex assertions"
    ],
    "traps": "Maintain clean syllable boundaries without dropping grammatical particles ('the' before superlatives, 'to' with 'allergic to', 'on' with 'congratulations on').",
