            "textEn": "The surge was caused by unoptimized automated data analytics jobs running on on-demand GPU instances without reserved instance pricing commitments.",
            "textHi": "यह वृद्धि ऑन-डिमांड जीपीयू इंस्टेंसेस पर बिना छूट वाले मूल्यों के डेटा एनालिटिक्स जॉब्स चलाने के कारण हुई थी।"
